class SelfServiceAccountDto {
  final String contactEmail;
  final String contactPhone;
  final String contactLandline;
  final String realName;
  final String status;
  final String userGroup;
  final String location;
  final int allowedDevices;

  const SelfServiceAccountDto({
    required this.contactEmail,
    required this.contactPhone,
    required this.contactLandline,
    required this.realName,
    required this.status,
    required this.userGroup,
    required this.location,
    required this.allowedDevices,
  });

  @override
  int get hashCode =>
      contactEmail.hashCode ^
      contactPhone.hashCode ^
      contactLandline.hashCode ^
      realName.hashCode ^
      status.hashCode ^
      userGroup.hashCode ^
      location.hashCode ^
      allowedDevices.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SelfServiceAccountDto &&
          runtimeType == other.runtimeType &&
          contactEmail == other.contactEmail &&
          contactPhone == other.contactPhone &&
          contactLandline == other.contactLandline &&
          realName == other.realName &&
          status == other.status &&
          userGroup == other.userGroup &&
          location == other.location &&
          allowedDevices == other.allowedDevices;
}

